// Generated by scripts/generate-art-records.ts. Do not edit by hand.
//
// Every founding Game's full roster is represented. Each record names the publisher source it
// was taken from, the review basis, and the SHA-256 of both delivered files: the character page
// image at /art and the roster thumbnail at /art/thumb. `npm run verify:art` checks both.
import type { CharacterArtAsset } from '../types/domain';

export interface PromotionalArtRecord extends CharacterArtAsset {
  gameSlug: string;
  characterSlug: string;
}

const reviewedAt = '2026-09-20';

const deliveryNote = 'Delivered as WebP re-encoded from the publisher source at display resolution; the source URL identifies the original asset.';
const arcPromotionalEvidence = `Official publisher-hosted promotional asset. Arc System Works fan-content guidance does not grant direct official-visual reuse; included under accepted ADR-023 with the restriction and per-asset removal path recorded. ${deliveryNote}`;
const ggstFanKitEvidence = `Official fan-kit permits non-commercial use by individuals or unincorporated organizations with a visible notice and compliant processing. Re-review is required before monetization or an operator-status change. ${deliveryNote}`;
const uni2FanKitEvidence = `Official fan-kit terms permit website use and redistribution with notice and an official-site link. ${deliveryNote}`;
const riotCommunityEvidence = `Riot permits revocable non-commercial community use under its Legal Jibber Jabber policy. MainStation is a free community PWA with original profile and statistical content, and the required project notice is displayed; re-review is required if scope or monetization changes. ${deliveryNote}`;
const capcomPromotionalEvidence = `Official Capcom-hosted promotional art. Capcom fan-content guidance does not grant unchanged public display and excludes relevant third-party IP where applicable; included under accepted ADR-023 with the restriction and removal path recorded. ${deliveryNote}`;
const playstationPromotionalEvidence = `Official PlayStation-hosted promotional art. PlayStation website terms reserve copying and public display absent express permission; included under accepted ADR-023 with the restriction and removal path recorded. ${deliveryNote}`;
const nintendoPromotionalEvidence = `Official Super Smash Bros. Ultimate promotional render used as a clearly labeled cross-version identity fallback for Melee. Nintendo terms do not grant this public display; included under accepted ADR-023 with the mismatch and removal path recorded. ${deliveryNote}`;
const wbPromotionalEvidence = `Official Mortal Kombat 1 roster art. The official Kommunity Kit is a community-use signal but provides no general app license; included under accepted ADR-023 with the limitation and removal path recorded. ${deliveryNote}`;
const bandaiPromotionalEvidence = `Official TEKKEN 8 roster thumbnail served by Bandai Namco's own media host. Bandai Namco terms reserve reuse absent express permission; included under accepted ADR-023 with the limitation and removal path recorded. ${deliveryNote}`;

type ArtInput = Omit<PromotionalArtRecord, 'reviewedAt'>;
const record = (input: ArtInput): PromotionalArtRecord => ({ ...input, reviewedAt });

const riotArt = (characterSlug: string, sourceUrl: string, assetHash: string, thumbHash: string): PromotionalArtRecord => record({
  gameSlug: '2xko',
  characterSlug,
  localPath: `/art/2xko-${characterSlug}.webp`,
  sourceUrl,
  sourcePublisher: 'Riot Games',
  reviewUrl: 'https://www.riotgames.com/en/legal',
  creditText: 'MainStation was created under Riot Games\' "Legal Jibber Jabber" policy using assets owned by Riot Games. Riot Games does not endorse or sponsor this project.',
  usageBasis: 'conditional-community-policy',
  permissionEvidence: riotCommunityEvidence,
  assetHash: `sha256:${assetHash}`,
  thumbHash: `sha256:${thumbHash}`,
});

